-- Regionen früherer Stände, die in diesem Stand nicht mehr vorkommen.
update public.regions
   set is_active = false
 where country_id = 'DE'
   and is_active
   and source <> 'GV100AD Stand 30.09.2026';

-- Gemeindezahlen aus den aktiven Gemeinden neu berechnen (berücksichtigt auch deaktivierte Regionen).
select private.refresh_region_municipality_counts('DE');

-- Plausibilitätsprüfung: bricht die Migration ab, wenn der Datenbestand nicht zum Import passt.
do $$
declare
  v_states integer;
  v_districts integer;
  v_municipalities integer;
  v_country_count integer;
begin
  select count(*) filter (where level = 'state'),
         count(*) filter (where level = 'district'),
         count(*) filter (where level = 'municipality')
    into v_states, v_districts, v_municipalities
    from public.regions
   where country_id = 'DE' and is_active;
  select municipality_count into v_country_count from public.regions where id = 'DE';
  if v_states <> 16 or v_districts <> 401 or v_municipalities <> 10749 or v_country_count <> 10749 then
    raise exception 'GV100AD-Import inkonsistent: % Länder, % Kreise, % Gemeinden, Gemeindezahl DE %',
      v_states, v_districts, v_municipalities, v_country_count;
  end if;
end
$$;
